def solve(nums, target):
    """
    Given a list of integers nums and a target integer, find two indices i and j such that nums[i] + nums[j] == target.
    """
    num_map = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_map:
            return [num_map[complement], i]
        num_map[num] = i
    return []
```

