def solve(nums):
    n = len(nums)
    if n == 0:
        return 0

    tails = []  # Store the smallest tail of all increasing subsequences with length i+1 in tails[i].

    for num in nums:
        if not tails or num > tails[-1]:
            tails.append(num)
        else:
            # Binary search to find the smallest tail >= num
            l, r = 0, len(tails) - 1
            while l <= r:
                mid = (l + r) // 2
                if tails[mid] < num:
                    l = mid + 1
                else:
                    r = mid - 1
            tails[l] = num

    return len(tails)
